/// PageLamp's own radii (spec §4.4). Windows, sheets, popovers, controls, sidebar and inspector use the system's.
nonisolated enum PLRadius {
    /// `radius.callout` — Callouts, choice tiles, cards (.containerShape(.rect(cornerRadius: 12))).
    static let callout: CGFloat = 12

    /// `radius.row` — Row hover/focus fills.
    static let row: CGFloat = 8

    /// `radius.inner-min` — Minimum of a concentric inner shape (ConcentricRectangle(corners: .concentric(minimum: .fixed(6)))).
    static let innerMin: CGFloat = 6

    /// Concentric inner radius (spec §4.4): `max(innerMin, outer − padding)`.
    static func concentric(outer: CGFloat, padding: CGFloat) -> CGFloat {
        max(innerMin, outer - padding)
    }
}

