/// Animations (spec §5, §10.4). Under Reduce Motion use PLMotion.reduced or no animation.
nonisolated enum PLMotion {
    /// A spring token as Core Animation takes it: the SwiftUI spring's perceptual duration and
    /// bounce (`CASpringAnimation(perceptualDuration:bounce:)` moves like the SwiftUI spring).
    struct Spring: Sendable {
        let duration: Double
        let bounce: Double
    }

    /// `motion.calm`
    static let calm: Animation = .smooth(duration: 0.45)

    /// `motion.calm` for Core Animation: `CASpringAnimation(perceptualDuration:bounce:)`.
    static let calmSpring = Spring(duration: 0.45, bounce: 0)

    /// `motion.quick`
    static let quick: Animation = .snappy(duration: 0.3)

    /// `motion.quick` for Core Animation: `CASpringAnimation(perceptualDuration:bounce:)`.
    static let quickSpring = Spring(duration: 0.3, bounce: 0.15)

    /// `motion.lively` — Only the one "Sync finished" bounce.
    static let lively: Animation = .bouncy

    /// `motion.lively` for Core Animation: `CASpringAnimation(perceptualDuration:bounce:)`.
    static let livelySpring = Spring(duration: 0.5, bounce: 0.3)

    /// `motion.week`
    static let week: Animation = .smooth(duration: 0.35)

    /// `motion.week` for Core Animation: `CASpringAnimation(perceptualDuration:bounce:)`.
    static let weekSpring = Spring(duration: 0.35, bounce: 0)

    /// `motion.section`
    static let section: Animation = .smooth(duration: 0.25)

    /// `motion.section` for Core Animation: `CASpringAnimation(perceptualDuration:bounce:)`.
    static let sectionSpring = Spring(duration: 0.25, bounce: 0)

    /// `motion.step`
    static let step: Animation = .smooth(duration: 0.4)

    /// `motion.step` for Core Animation: `CASpringAnimation(perceptualDuration:bounce:)`.
    static let stepSpring = Spring(duration: 0.4, bounce: 0)

    /// `motion.hover` — Row hover fill; none under Reduce Highlighting Effects.
    static let hover: Animation = .easeOut(duration: 0.15)

    /// `motion.reduced` — Everything under Reduce Motion: a crossfade (or instant).
    static let reduced: Animation = .easeInOut(duration: 0.2)
}

/// One appearance's colour: sRGB, or Display P3 for a token outside sRGB.
nonisolated private struct PLRGBA: Sendable {
    enum Space: Sendable { case sRGB, displayP3 }

    let space: Space
    let red: CGFloat
    let green: CGFloat
    let blue: CGFloat
    let alpha: CGFloat

    static func sRGB(_ red: CGFloat, _ green: CGFloat, _ blue: CGFloat, _ alpha: CGFloat = 1) -> PLRGBA {
        PLRGBA(space: .sRGB, red: red, green: green, blue: blue, alpha: alpha)
    }

    static func displayP3(_ red: CGFloat, _ green: CGFloat, _ blue: CGFloat, _ alpha: CGFloat = 1) -> PLRGBA {
        PLRGBA(space: .displayP3, red: red, green: green, blue: blue, alpha: alpha)
    }

    var nsColor: NSColor {
        switch space {
        case .sRGB: NSColor(srgbRed: red, green: green, blue: blue, alpha: alpha)
        case .displayP3: NSColor(displayP3Red: red, green: green, blue: blue, alpha: alpha)
        }
    }
}

/// A colour that follows the view's appearance, Increase Contrast included (no asset catalog needed).
/// The high-contrast names come first so they win whenever the appearance is a high-contrast one.
/// The provider is @Sendable and nonisolated: AppKit may resolve colours off the main thread, where a
/// closure inferred as MainActor (a target with MainActor default isolation) would trap.
nonisolated private func plDynamicColor(light: PLRGBA, dark: PLRGBA, highContrastLight: PLRGBA, highContrastDark: PLRGBA) -> Color {
    Color(nsColor: NSColor(name: nil) { @Sendable appearance in
        switch appearance.bestMatch(from: [.accessibilityHighContrastAqua, .accessibilityHighContrastDarkAqua, .aqua, .darkAqua]) {
        case .darkAqua?: dark.nsColor
        case .accessibilityHighContrastAqua?: highContrastLight.nsColor
        case .accessibilityHighContrastDarkAqua?: highContrastDark.nsColor
        default: light.nsColor
        }
    })
}
